package misc

import (
	_ "embed"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/core/tracing"
	"github.com/ethereum/go-ethereum/core/vm"
	"github.com/ethereum/go-ethereum/crypto"
	"github.com/ethereum/go-ethereum/params"
)

// Mantle Hoodi BVM upgrade.
//
// Mantle Hoodi's genesis was generated by an L2Genesis script that etched BVM_ETH without running
// its constructor (empty immutables and name/symbol) and never wrote LegacyERC20MNT (BVM_MNT).
// Neither address is a proxy and no transaction can place code at a fixed address, so the
// MantleHoodiBvmUpgrade hardfork writes the correct runtime code before any transaction of a block
// executes. It mirrors alloy-op-evm's ensure_bvm_predeploys (mantle-v2
// rust/alloy-op-evm/src/block/hoodi_bvm_upgrade.rs) byte for byte, so op-geth and op-reth compute
// the same state root.
//
// The write happens once, in the activation block: the first block that is active while the block
// one params.MantleHoodiBlockTime earlier is not. alloy-op-evm uses the same condition rather than
// Canyon's "time equals the fork time" check, so both clients write in the same block whether or
// not the activation time equals a block timestamp. Storage, balance and nonce are left untouched.
//
// The bytecode is the runtime code of BVM_ETH and of LegacyERC20MNT constructed with Hoodi's L1 MNT
// address 0xb57837B4D0d372bF49E69Bc36c36d9Cc9488bf18, compiled from mantle-v2
// packages/contracts-bedrock (solc 0.8.15); test/HoodiBvmUpgradeBytecode.t.sol there pins it.

// mantleBvmEthCode is the BVM_ETH runtime code written by the upgrade.
//
//go:embed bvm_eth.bin
var mantleBvmEthCode []byte

// mantleLegacyERC20MNTCode is the LegacyERC20MNT runtime code written by the upgrade.
//
//go:embed legacy_erc20_mnt.bin
var mantleLegacyERC20MNTCode []byte

var (
	// MantleBvmEthAddr is the BVM_ETH predeploy address.
	MantleBvmEthAddr = common.HexToAddress("0xdEAddEaDdeadDEadDEADDEAddEADDEAddead1111")
	// MantleLegacyERC20MNTAddr is the LegacyERC20MNT (BVM_MNT) predeploy address.
	MantleLegacyERC20MNTAddr = common.HexToAddress("0xDeadDeAddeAddEAddeadDEaDDEAdDeaDDeAD0000")

	// MantleBvmEthCodeHash is the code hash of the BVM_ETH runtime code written by the upgrade.
	MantleBvmEthCodeHash = common.HexToHash("0xe84a8d4d3ed629a670b03e88dab806078de4b86beac8ca06addcff8dd4996290")
	// MantleLegacyERC20MNTCodeHash is the code hash of the LegacyERC20MNT runtime code written by
	// the upgrade (Mantle Hoodi only).
	MantleLegacyERC20MNTCodeHash = common.HexToHash("0xf165e4b851dc8d4e18dcf1d2bc59817d0129a39365c191e76bfd596b60513b45")

	mantleHoodiBvmUpgradeCodes = []struct {
		addr common.Address
		hash common.Hash
		code []byte
	}{
		{MantleBvmEthAddr, MantleBvmEthCodeHash, mantleBvmEthCode},
		{MantleLegacyERC20MNTAddr, MantleLegacyERC20MNTCodeHash, mantleLegacyERC20MNTCode},
	}
)

func init() {
	for _, c := range mantleHoodiBvmUpgradeCodes {
		if crypto.Keccak256Hash(c.code) != c.hash {
			panic("mantle hoodi bvm upgrade: embedded code does not match its code hash")
		}
	}
}

// ApplyMantleHoodiBvmUpgrade writes the BVM_ETH and LegacyERC20MNT runtime code on Mantle Hoodi in the
// activation block of the MantleHoodiBvmUpgrade fork. It must run before the block's transactions.
func ApplyMantleHoodiBvmUpgrade(config *params.ChainConfig, time uint64, statedb vm.StateDB) {
	// The previous block time saturates at zero, as in alloy-op-evm.
	var prev uint64
	if time > params.MantleHoodiBlockTime {
		prev = time - params.MantleHoodiBlockTime
	}
	if config.ChainID == nil || config.ChainID.Cmp(params.MantleHoodiChainId) != 0 ||
		!config.IsMantleHoodiBvmUpgrade(time) || config.IsMantleHoodiBvmUpgrade(prev) {
		return
	}
	for _, c := range mantleHoodiBvmUpgradeCodes {
		statedb.SetCode(c.addr, c.code, tracing.CodeChangeUnspecified)
	}
}
